66	impl TarballSlot {
67	    /// Rebuild a slot from its journaled parts so startup recovery can
68	    /// re-run [`Storage::finalize_tarball_slot`] on it.
69	    pub(crate) fn from_parts(tmp_path: PathBuf, name: PackageName, filename: String) -> Self {
70	        Self { tmp_path, name, filename }
