1162	    // resolves to is the `version` matched below, which may differ for a
1163	    // non-canonical upstream tarball name.
1164	    let (filename, name_version) = match name.parse_tarball_name(filename) {
1165	        Ok(parsed) => parsed,
1166	        Err(err) => return error_response(&err),
1167	    };
1168	    if let Err(err) = authorize(state, identity, name.as_str(), Action::Access) {
1169	        return error_response(&err);
1170	    }
1171	    if let Err(err) = ensure_osv_allowed(state, &name, &name_version) {
