1176	    // plain miss, which surfaces as `Ok(None)`) must fail closed rather
1177	    // than fall through to upstream and serve bytes of a different
1178	    // provenance for the same package name.
1179	    match state.inner.storage.open_hosted_tarball(&name, &filename).await {
1180	        Ok(Some((body, len))) => return tarball_response(body, len),
1181	        Ok(None) => {}
1182	        Err(err) => {
